const raw = $input.first().json.text || '';

let data;
try {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```/g, '').trim();
  data = JSON.parse(cleaned);
} catch (e) {
  return [{ json: { html: '<div style="font-family:sans-serif;padding:40px;text-align:center;"><h2 style="color:#ef4444;">Parsing Error</h2><p>Could not parse AI response. Please try again.</p></div>' } }];
}

const score = Number(data.toxicity_score) || 0;

const verdictMap = {
  'SAFE':      { bg: '#22c55e', label: 'SAFE TO WORK WITH' },
  'CAUTION':   { bg: '#f59e0b', label: 'PROCEED WITH CAUTION' },
  'DANGER':    { bg: '#f97316', label: 'HIGH RISK CLIENT' },
  'RUN AWAY':  { bg: '#ef4444', label: 'RUN AWAY' }
};
const vc = verdictMap[data.verdict] || { bg: '#6b7280', label: data.verdict || 'UNKNOWN' };

const scoreColor = score <= 30 ? '#22c55e' : score <= 55 ? '#f59e0b' : score <= 75 ? '#f97316' : '#ef4444';

const li = function(arr, color) {
  return (arr || []).map(function(item) {
    const flag = item.flag || item;
    const reason = item.reason || '';
    return '<li style="margin-bottom:8px;line-height:1.5;color:#374151;">'
      + '<span style="font-weight:600;">' + flag + '</span>'
      + (reason ? '<br><span style="font-size:11px;color:#9ca3af;">' + reason + '</span>' : '')
      + '</li>';
  }).join('');
};

const simpleLi = function(arr) {
  return (arr || []).map(function(i) {
    return '<li style="margin-bottom:6px;line-height:1.5;color:#374151;">' + i + '</li>';
  }).join('');
};

const redSection = (data.red_flags && data.red_flags.length > 0)
  ? '<div style="background:#fef2f2;border:1px solid #fecaca;border-radius:14px;padding:20px;margin-bottom:14px;">'
    + '<h3 style="margin:0 0 12px;font-size:13px;text-transform:uppercase;letter-spacing:1px;color:#dc2626;font-weight:700;">Red Flags - Serious Concerns</h3>'
    + '<ul style="margin:0;padding-left:18px;">' + li(data.red_flags) + '</ul>'
    + '</div>'
  : '';

const yellowSection = (data.yellow_flags && data.yellow_flags.length > 0)
  ? '<div style="background:#fffbeb;border:1px solid #fde68a;border-radius:14px;padding:20px;margin-bottom:14px;">'
    + '<h3 style="margin:0 0 12px;font-size:13px;text-transform:uppercase;letter-spacing:1px;color:#b45309;font-weight:700;">Yellow Flags - Watch These</h3>'
    + '<ul style="margin:0;padding-left:18px;">' + li(data.yellow_flags) + '</ul>'
    + '</div>'
  : '';

const greenSection = (data.green_flags && data.green_flags.length > 0)
  ? '<div style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:14px;padding:20px;margin-bottom:14px;">'
    + '<h3 style="margin:0 0 12px;font-size:13px;text-transform:uppercase;letter-spacing:1px;color:#15803d;font-weight:700;">Green Flags - Positive Signs</h3>'
    + '<ul style="margin:0;padding-left:18px;">' + li(data.green_flags) + '</ul>'
    + '</div>'
  : '';

const tipsSection = (data.protection_tips && data.protection_tips.length > 0)
  ? '<div style="background:#f0f9ff;border:1px solid #bae6fd;border-radius:14px;padding:20px;margin-bottom:20px;">'
    + '<h3 style="margin:0 0 12px;font-size:13px;text-transform:uppercase;letter-spacing:1px;color:#0369a1;font-weight:700;">If You Still Take This Project</h3>'
    + '<ul style="margin:0;padding-left:18px;">' + simpleLi(data.protection_tips) + '</ul>'
    + '</div>'
  : '';

const html =
  '<div style="font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,sans-serif;max-width:700px;margin:0 auto;padding:20px;">'

  + '<div style="background:linear-gradient(135deg,#1a1a2e 0%,#16213e 100%);border-radius:20px;padding:36px;text-align:center;margin-bottom:20px;box-shadow:0 8px 32px rgba(0,0,0,0.3);">'
    + '<div style="font-size:13px;font-weight:600;color:rgba(255,255,255,0.5);text-transform:uppercase;letter-spacing:2px;margin-bottom:8px;">TOXICITY SCORE</div>'
    + '<div style="font-size:88px;font-weight:900;color:' + scoreColor + ';line-height:1;text-shadow:0 0 30px ' + scoreColor + '40;">' + score + '</div>'
    + '<div style="font-size:15px;color:rgba(255,255,255,0.4);margin:2px 0 20px;">out of 100</div>'
    + '<div style="display:inline-flex;align-items:center;gap:8px;background:' + vc.bg + ';color:#fff;padding:10px 28px;border-radius:99px;font-size:15px;font-weight:800;letter-spacing:0.5px;">'
      + vc.label
    + '</div>'
    + '<p style="margin:16px auto 0;font-size:13px;color:rgba(255,255,255,0.7);max-width:500px;line-height:1.6;">' + (data.verdict_reason || '') + '</p>'
  + '</div>'

  + redSection
  + yellowSection
  + greenSection
  + tipsSection

  + '<div style="text-align:center;color:#d1d5db;font-size:11px;padding-top:16px;border-top:1px solid #f3f4f6;">'
    + 'Powered by n8n + OpenAI · Always use your own judgment'
  + '</div>'

  + '</div>';

return [{ json: { html } }];
